// ParseHex converts a hexadecimal number represented as a string into its
// decimal equivalent, using first principles (no built-in base-conversion
// libraries).
func ParseHex(in string) (int64, error) {
	if len(in) == 0 {
		return 0, errors.New("syntax error: empty string")
	}

	var result int64
	for _, c := range in {
		var digit int64
		switch {
		case c >= '0' && c <= '9':
			digit = int64(c - '0')
		case c >= 'a' && c <= 'f':
			digit = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			digit = int64(c-'A') + 10
		default:
			return 0, fmt.Errorf("syntax error: invalid character %q", c)
		}

		if result > (math.MaxInt64-digit)/16 {
			return 0, fmt.Errorf("range error: value out of range for %q", in)
		}

		result = result*16 + digit
	}

	return result, nil
}

// HandleErrors takes a list of inputs for ParseHex and returns a matching
// list of error cases: "none", "syntax", or "range".
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		case containsSyntax(err):
			results[i] = "syntax"
		default:
			results[i] = "range"
		}
	}
	return results
}

func containsSyntax(err error) bool {
	msg := err.Error()
	for i := 0; i+len("syntax") <= len(msg); i++ {
		if msg[i:i+len("syntax")] == "syntax" {
			return true
		}
	}
	return false
}
"}

